206	// runCleanSession handles the --session flag: clean/reset a single session.
207	// actionVerb is the capitalized verb (e.g., "Clean" or "Reset") and pastVerb
208	// is the past tense (e.g., "cleaned" or "reset") used in user-facing messages.
209	func runCleanSession(ctx context.Context, cmd *cobra.Command, strat *strategy.ManualCommitStrategy, sessionID string, force, dryRun bool, actionVerb, pastVerb string) error {
210		// Verify the session exists
211		state, err := strategy.LoadSessionState(ctx, sessionID)
212		if err != nil {
213			return fmt.Errorf("failed to load session: %w", err)
214		}
215		if state == nil {
216			return fmt.Errorf("session not found: %s", sessionID)
217		}
218	
219		if dryRun {
220			w := cmd.OutOrStdout()
221			fmt.Fprintf(w, "Would %s session %s (phase: %s, checkpoints: %d)\n", strings.ToLower(actionVerb), sessionID, state.Phase, state.StepCount)
222			return nil
223		}
224	
225		if !force {
226			var confirmed bool
227	
228			title := fmt.Sprintf("%s session %s?", actionVerb, sessionID)
229			description := fmt.Sprintf("Phase: %s, Checkpoints: %d", state.Phase, state.StepCount)
230	
231			form := NewAccessibleForm(
232				huh.NewGroup(
233					huh.NewConfirm().
234						Title(title).
235						Description(description).
236						Value(&confirmed),
237				),
238			)
239	
240			if err := form.Run(); err != nil {
241				if errors.Is(err, huh.ErrUserAborted) {
242					return nil
243				}
244				return fmt.Errorf("failed to get confirmation: %w", err)
245			}
246	
247			if !confirmed {
248				return nil
249			}
250		}
251	
252		if err := strat.ResetSession(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionID); err != nil {
253			return fmt.Errorf("%s session failed: %w", strings.ToLower(actionVerb), err)
254		}
255	
256		fmt.Fprintf(cmd.OutOrStdout(), "Session %s has been %s. File changes remain in the working directory.\n", sessionID, pastVerb)
257		return nil
258	}
