278	// runCleanAllWithItems is the core logic for cleaning all orphaned items.
279	// Separated for testability — tests pass a cmd without a TTY and use force or dryRun to avoid prompts.
280	func runCleanAllWithItems(ctx context.Context, cmd *cobra.Command, force, dryRun bool, items []strategy.CleanupItem, tempFiles []string) error {
281		w := cmd.OutOrStdout()
282		errW := cmd.ErrOrStderr()
283		// Handle no items case
284		if len(items) == 0 && len(tempFiles) == 0 {
285			fmt.Fprintln(w, "No orphaned items to clean up.")
286			return nil
287		}
288	
289		// Group items by type for display
290		var branches, states, checkpoints []strategy.CleanupItem
291		for _, item := range items {
292			switch item.Type {
293			case strategy.CleanupTypeShadowBranch:
294				branches = append(branches, item)
295			case strategy.CleanupTypeSessionState:
296				states = append(states, item)
297			case strategy.CleanupTypeCheckpoint:
298				checkpoints = append(checkpoints, item)
299			}
300		}
301	
302		// Show preview when not in force mode
303		if !force || dryRun {
304			totalItems := len(items) + len(tempFiles)
305			fmt.Fprintf(w, "Found %d %s to clean:\n\n", totalItems, itemWord(totalItems))
306	
307			if len(branches) > 0 {
308				fmt.Fprintf(w, "Shadow branches (%d):\n", len(branches))
309				for _, item := range branches {
310					fmt.Fprintf(w, "  %s\n", item.ID)
311				}
312				fmt.Fprintln(w)
313			}
314	
315			if len(states) > 0 {
316				fmt.Fprintf(w, "Session states (%d):\n", len(states))
317				for _, item := range states {
318					fmt.Fprintf(w, "  %s\n", item.ID)
319				}
320				fmt.Fprintln(w)
321			}
322	
323			if len(checkpoints) > 0 {
324				fmt.Fprintf(w, "Checkpoint metadata (%d):\n", len(checkpoints))
325				for _, item := range checkpoints {
326					fmt.Fprintf(w, "  %s\n", item.ID)
327				}
328				fmt.Fprintln(w)
329			}
330	
331			if len(tempFiles) > 0 {
332				fmt.Fprintf(w, "Temp files (%d):\n", len(tempFiles))
333				for _, file := range tempFiles {
334					fmt.Fprintf(w, "  %s\n", file)
335				}
336				fmt.Fprintln(w)
337			}
338	
339			if dryRun {
340				fmt.Fprintln(w, "Run without --dry-run to delete these items.")
341				return nil
342			}
343	
344			// Prompt for confirmation
345			var confirmed bool
346			form := NewAccessibleForm(
347				huh.NewGroup(
348					huh.NewConfirm().
349						Title(fmt.Sprintf("Delete %d %s?", totalItems, itemWord(totalItems))).
350						Value(&confirmed),
351				),
352			)
353			if err := form.Run(); err != nil {
354				if errors.Is(err, huh.ErrUserAborted) {
355					return nil
356				}
357				return fmt.Errorf("failed to get confirmation: %w", err)
358			}
359			if !confirmed {
360				return nil
361			}
362		}
363	
364		// Force mode - delete items
365		result, err := strategy.DeleteAllCleanupItems(ctx, items)
366		if err != nil {
367			return fmt.Errorf("failed to delete orphaned items: %w", err)
368		}
369	
370		// Delete temp files
371		deletedTempFiles, failedTempFiles := deleteTempFiles(ctx, tempFiles)
372	
373		// Report results
374		totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints) + len(deletedTempFiles)
375		totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints) + len(failedTempFiles)
376	
377		if totalDeleted > 0 {
378			fmt.Fprintf(w, "✓ Deleted %d %s:\n", totalDeleted, itemWord(totalDeleted))
379	
380			if len(result.ShadowBranches) > 0 {
381				fmt.Fprintf(w, "\nShadow branches (%d):\n", len(result.ShadowBranches))
382				for _, branch := range result.ShadowBranches {
383					fmt.Fprintf(w, "  %s\n", branch)
384				}
385			}
386	
387			if len(result.SessionStates) > 0 {
388				fmt.Fprintf(w, "\nSession states (%d):\n", len(result.SessionStates))
389				for _, state := range result.SessionStates {
390					fmt.Fprintf(w, "  %s\n", state)
391				}
392			}
393	
394			if len(result.Checkpoints) > 0 {
395				fmt.Fprintf(w, "\nCheckpoints (%d):\n", len(result.Checkpoints))
396				for _, cp := range result.Checkpoints {
397					fmt.Fprintf(w, "  %s\n", cp)
398				}
399			}
400	
401			if len(deletedTempFiles) > 0 {
402				fmt.Fprintf(w, "\nTemp files (%d):\n", len(deletedTempFiles))
403				for _, file := range deletedTempFiles {
404					fmt.Fprintf(w, "  %s\n", file)
405				}
406			}
407		}
408	
409		if totalFailed > 0 {
410			fmt.Fprintf(errW, "\nFailed to delete %d %s:\n", totalFailed, itemWord(totalFailed))
411	
412			if len(result.FailedBranches) > 0 {
413				fmt.Fprintf(errW, "\nShadow branches:\n")
414				for _, branch := range result.FailedBranches {
415					fmt.Fprintf(errW, "  %s\n", branch)
416				}
417			}
418	
419			if len(result.FailedStates) > 0 {
420				fmt.Fprintf(errW, "\nSession states:\n")
421				for _, state := range result.FailedStates {
422					fmt.Fprintf(errW, "  %s\n", state)
423				}
424			}
425	
426			if len(result.FailedCheckpoints) > 0 {
427				fmt.Fprintf(errW, "\nCheckpoints:\n")
428				for _, cp := range result.FailedCheckpoints {
429					fmt.Fprintf(errW, "  %s\n", cp)
430				}
431			}
432	
433			if len(failedTempFiles) > 0 {
434				fmt.Fprintf(errW, "\nTemp files:\n")
435				for _, fe := range failedTempFiles {
436					fmt.Fprintf(errW, "  %s: %v\n", fe.File, fe.Err)
437				}
438			}
439	
440			return fmt.Errorf("failed to delete %d %s", totalFailed, itemWord(totalFailed))
441		}
442	
443		return nil
444	}
