122	func (s *ManualCommitStrategy) ListOrphanedItems(ctx context.Context) ([]CleanupItem, error) {
123		var items []CleanupItem
124	
125		// Shadow branches (should have been auto-cleaned after condensation)
126		branches, err := ListShadowBranches(ctx)
127		if err != nil {
128			return nil, err
129		}
130		for _, branch := range branches {
131			items = append(items, CleanupItem{
132				Type:   CleanupTypeShadowBranch,
133				ID:     branch,
134				Reason: "shadow branch (should have been auto-cleaned)",
135			})
136		}
137	
138		// Orphaned session states are detected by ListOrphanedSessionStates
139		// which is strategy-agnostic (checks both shadow branches and checkpoints)
140	
141		return items, nil
142	}
