20	// Reset deletes the shadow branch and session state for the current HEAD.
21	// This allows starting fresh without existing checkpoints.
22	func (s *ManualCommitStrategy) Reset(ctx context.Context, w, errW io.Writer) error {
23		repo, err := OpenRepository(ctx)
24		if err != nil {
25			return fmt.Errorf("failed to open git repository: %w", err)
26		}
27	
28		// Get current HEAD
29		head, err := repo.Head()
30		if err != nil {
31			return fmt.Errorf("failed to get HEAD: %w", err)
32		}
33	
34		// Get current worktree ID for shadow branch naming
35		worktreePath, err := paths.WorktreeRoot(ctx)
36		if err != nil {
37			return fmt.Errorf("failed to get worktree path: %w", err)
38		}
39		worktreeID, err := paths.GetWorktreeID(worktreePath)
40		if err != nil {
41			return fmt.Errorf("failed to get worktree ID: %w", err)
42		}
43	
44		// Get shadow branch name for current HEAD
45		shadowBranchName := getShadowBranchNameForCommit(head.Hash().String(), worktreeID)
46	
47		// Check if shadow branch exists
48		refName := plumbing.NewBranchReferenceName(shadowBranchName)
49		_, err = repo.Reference(refName, true)
50		hasShadowBranch := err == nil
51	
52		// Find sessions for this commit
53		sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
54		if err != nil {
55			sessions = nil // Ignore error, treat as no sessions
56		}
57	
58		// If nothing to clean, return early
59		if !hasShadowBranch && len(sessions) == 0 {
60			fmt.Fprintf(w, "Nothing to clean for %s\n", shadowBranchName)
61			return nil
62		}
63	
64		// Clear all sessions for this commit
65		clearedSessions := make([]string, 0)
66		for _, state := range sessions {
67			if err := s.clearSessionState(ctx, state.SessionID); err != nil {
68				fmt.Fprintf(errW, "Warning: failed to clear session state for %s: %v\n", state.SessionID, err)
69			} else {
70				clearedSessions = append(clearedSessions, state.SessionID)
71			}
72		}
73	
74		// Report cleared session states with session IDs
75		if len(clearedSessions) > 0 {
76			for _, sessionID := range clearedSessions {
77				fmt.Fprintf(w, "✓ Cleared session state for %s\n", sessionID)
78			}
79		}
80	
81		// Delete the shadow branch if it exists
82		if hasShadowBranch {
83			if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
84				return fmt.Errorf("failed to delete shadow branch: %w", err)
85			}
86			fmt.Fprintf(w, "✓ Deleted shadow branch %s\n", shadowBranchName)
87		}
88	
89		return nil
90	}
