92	// ResetSession clears a single session's state and removes the shadow branch
93	// if no other sessions reference it. File changes remain in the working directory.
94	func (s *ManualCommitStrategy) ResetSession(ctx context.Context, w, errW io.Writer, sessionID string) error {
95		// Load the session state
96		state, err := s.loadSessionState(ctx, sessionID)
97		if err != nil {
98			return fmt.Errorf("failed to load session state: %w", err)
99		}
100		if state == nil {
101			return fmt.Errorf("session not found: %s", sessionID)
102		}
103	
104		// Clear the session state file
105		if err := s.clearSessionState(ctx, sessionID); err != nil {
106			return fmt.Errorf("failed to clear session state: %w", err)
107		}
108		fmt.Fprintf(w, "✓ Cleared session state for %s\n", sessionID)
109	
110		// Determine the shadow branch for this session
111		shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
112	
113		// Open repository
114		repo, err := OpenRepository(ctx)
115		if err != nil {
116			return fmt.Errorf("failed to open repository: %w", err)
117		}
118	
119		// Clean up shadow branch if no other sessions need it
120		if err := s.cleanupShadowBranchIfUnused(ctx, repo, shadowBranchName, sessionID); err != nil {
121			fmt.Fprintf(errW, "Warning: failed to clean up shadow branch %s: %v\n", shadowBranchName, err)
122		} else {
123			// Check if it was actually deleted via git CLI (go-git's cache
124			// may be stale after CLI-based deletion with packed refs)
125			if err := branchExistsCLI(ctx, shadowBranchName); err != nil {
126				fmt.Fprintf(w, "✓ Deleted shadow branch %s\n", shadowBranchName)
127			}
128		}
129	
130		return nil
131	}
