33	func setupCleanTestRepo(t *testing.T) (*git.Repository, plumbing.Hash) {
34		t.Helper()
35	
36		dir := t.TempDir()
37		repo, err := git.PlainInit(dir, false)
38		if err != nil {
39			t.Fatalf("failed to init git repo: %v", err)
40		}
41	
42		t.Chdir(dir)
43		paths.ClearWorktreeRootCache()
44	
45		// Create initial commit
46		emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
47		obj := repo.Storer.NewEncodedObject()
48		if err := emptyTree.Encode(obj); err != nil {
49			t.Fatalf("failed to encode empty tree: %v", err)
50		}
51		emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
52		if err != nil {
53			t.Fatalf("failed to store empty tree: %v", err)
54		}
55	
56		sig := object.Signature{Name: "test", Email: "test@test.com"}
57		commit := &object.Commit{
58			TreeHash:  emptyTreeHash,
59			Author:    sig,
60			Committer: sig,
61			Message:   "initial commit",
62		}
63		commitObj := repo.Storer.NewEncodedObject()
64		if err := commit.Encode(commitObj); err != nil {
65			t.Fatalf("failed to encode commit: %v", err)
66		}
67		commitHash, err := repo.Storer.SetEncodedObject(commitObj)
68		if err != nil {
69			t.Fatalf("failed to store commit: %v", err)
70		}
71	
72		// Create HEAD and master references
73		headRef := plumbing.NewSymbolicReference(plumbing.HEAD, plumbing.NewBranchReferenceName("master"))
74		if err := repo.Storer.SetReference(headRef); err != nil {
75			t.Fatalf("failed to set HEAD: %v", err)
76		}
77		masterRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName("master"), commitHash)
78		if err := repo.Storer.SetReference(masterRef); err != nil {
79			t.Fatalf("failed to set master: %v", err)
80		}
81	
82		return repo, commitHash
83	}
