85	// createSessionStateFile creates a session state JSON file in .git/entire-sessions/.
86	func createSessionStateFile(t *testing.T, repoRoot string, sessionID string, commitHash plumbing.Hash) string {
87		t.Helper()
88	
89		sessionStateDir := filepath.Join(repoRoot, ".git", "entire-sessions")
90		if err := os.MkdirAll(sessionStateDir, 0o755); err != nil {
91			t.Fatalf("failed to create session state dir: %v", err)
92		}
93	
94		sessionFile := filepath.Join(sessionStateDir, sessionID+".json")
95		sessionState := map[string]any{
96			"session_id":       sessionID,
97			"base_commit":      commitHash.String(),
98			"checkpoint_count": 1,
99			"started_at":       time.Now().Format(time.RFC3339),
100		}
101		sessionData, err := json.Marshal(sessionState)
102		if err != nil {
103			t.Fatalf("failed to marshal session state: %v", err)
104		}
105		if err := os.WriteFile(sessionFile, sessionData, 0o600); err != nil {
106			t.Fatalf("failed to write session state file: %v", err)
107		}
108		return sessionFile
109	}
