368			LastCheckpoint: string(state.LastCheckpointID),
369			LastPrompt:     state.LastPrompt,
370			FilesTouched:   state.FilesTouched,
371		}
372		if state.TokenUsage != nil {
373			info.Tokens = &tokenInfoJSON{
374				Total:      totalTokens(state.TokenUsage),
375				Input:      state.TokenUsage.InputTokens,
376				CacheRead:  state.TokenUsage.CacheReadTokens,
